        'ブラウザーの編集ソフトでは、プレビューとエクスポートの結果がずれがちです。Darkroomはプレビューをお使いのGPUで、エクスポートを当社のGPUでレンダリングし、ゴールデンイメージによるテストハーネスで、両者の差を文書化された許容範囲内に保っています。',
        '重い処理はノートパソコンの外で行います。4Kのエクスポート、Whisperによる文字起こし、LUTでグレーディングした多層合成は、GPUレンダリングサーバーで実行されるため、薄型ノートでも作業を完了できます。',
