      ogDescription: '画像を公開して共有する前に、GPS位置情報、カメラ、撮影日時のメタデータを削除します。',
      intro: '写真の中には、もう一つの文書が入っています。スマートフォンやカメラは、ピクセルと一緒に、デバイスのメーカーとモデル、多くの場合はそのシリアル番号、レンズ、露出、シャッターが切られた正確な秒、最後にファイルを保存したソフトウェア、小さなプレビュー用サムネイル、そして位置情報サービスがオンだった場合は、あなたが立っていた場所の緯度、経度、高度を書き込みます。このツールは、JPG、PNG、WebP、HEICからそのすべてを読み取り、各タグを何が分かってしまうかでグループ分けして表示したうえで、ExifToolの一度の処理でまとめて削除します。共有するコピーには画像だけが残ります。',
