        'whisper-ctranslate2は--model medium --device cuda --compute_type float16 --vad_filter Trueと--output_format jsonで起動され、APIがそのJSONを解析して、選ばれた形式を自ら生成します。モデルはサーバー設定（WHISPER_CT2_MODEL）なので、mediumは既定値であり、保証ではありません。',
