        'コントラストを下げるのは、取り消すべき失敗ではなく、れっきとした表現の一つです。黒を0.25、白を0.75に写す計算式でそれを行えば、再現性のあるマットなルックになります。',
        'sRGB空間でチャンネルごとにコントラストをかけると、彩度が変わります。コントラストを付けると鮮やかな色はさらに鮮やかに、下げるとくすみますが、輝度で重み付けした階調レイヤーならこれを避けられます。',
