        '階調は、LをBT.709のルマ（0.2126 R + 0.7152 G + 0.0722 B）として計算し、四つの重みを求めます。シャドウは1 - smoothstep(0, 0.6, L)、ハイライトはsmoothstep(0.4, 1, L)、黒レベルは1 - smoothstep(0, 0.25, L)、白レベルはsmoothstep(0.75, 1, L)です。ここでsmoothstep(a, b, x)は、t = (x - a) / (b - a)をクランプしたときのtの二乗 × (3 - 2t)です。',
