      intro: 'トーンカーブは、自分で描いた線に沿って、入力のあらゆる階調を出力の階調に写像します。どのエディターでも、最も柔軟な階調・色調整ツールです。Apertureには、RGB、赤、緑、青の四本のカーブがあり、それぞれ2〜16個のドラッグ可能なポイントを持てます。さらに、写真上のカーソル位置の値にポイントを追加するスポイト「写真からポイントを選択」も備えています。ポイントを通るカーブは単調な三次曲線なので、ポイント間で行き過ぎたり逆向きになったりすることはありません。カーブは256エントリーのテーブルにサンプリングされ、GPUとエクスポートサーバーはどちらも線形補間でこのテーブルを読み取ります。レイヤースタックのガンマ空間の階調ステージで、三本のカラーカーブが先に、RGBカーブが最後に適用されます。ライブのヒストグラムを見ながら操作でき、レイヤーには通常どおりマスク、不透明度、描画モードのコントロールがあります。',
