        '各カーブは、三次エルミート基底関数（2t³ - 3t² + 1、t³ - 2t² + t、およびそれらの補完）を使ってx = i / 255の256個の値でサンプリングされ、0..1にクランプされます。最初のポイントより前のxはそのポイントのyを、最後のポイントより後のxはそのポイントのyを取ります。ピクセル値は、テーブルの最も近い二つのエントリー間の線形補間で読み取られます。これはGPUの線形サンプラーの動作と同じです。',
