        '輝度が保持されるので、色の補正が露出の問題に変わりません。階調を決めたあとにグレーディングしても、ヒストグラムは動きません。',
        'シャドウとハイライトを逆方向にシフトすることは、多くのフィルム調や映画調のルックの基本であり、九本のスライダーでそれを直接表現できます。',
