      privacyNote: 'カラーバランスは、ドロップした写真からブラウザ内で計算されます。補正そのものがお使いのマシンの外に出ることはありません。サインインしていない場合、プロジェクトはこのブラウザのIndexedDBに保持され、エクスポートするときにだけ、当社のサーバーで描画されるゲストの通常ジョブとしてアップロードされます。サインインしている場合は、元の画像、1920 pxのプレビュー、サムネイルが保存期間の設定に従ってプロジェクトとともに保持され、プロジェクトまたはアカウントを削除すると一緒に削除されます。ゲストのファイルは24時間保存されます。無料アカウントなら24時間から2年までの間で選べます。当社がファイルを第三者に渡すことはありません。',
