      intro: 'スプリットトーンは、写真の暗い階調にある色を、明るい階調に別の色を加える手法です。ティール＆オレンジのグレーディング、ハイライトを暖かくしたフィルムルック、サイアノタイプ風のモノクロは、どれもこの方法で作られます。Apertureでは、レイヤースタックの中で露光量、階調、ホワイトバランスのあとに適用されるガンマ空間のカラー処理として動作します。各ピクセルのBT.709のルマによって、シャドウの色相とハイライトの色相をそれぞれどれだけ受け取るかが決まり、「バランス」スライダーで、一方の重みが消えてもう一方の重みが現れる境目を動かします。この調整は最大64のレイヤーのうちの一つなので、不透明度を下げたり、マスクで範囲を限定したり、描画モードを「カラー」にして画像の輝度にまったく触れないようにしたりできます。',
