      intro: 'LUTは、入力のすべての色を出力の色に対応付けるルックアップテーブルです。カメラプロファイル、フィルムエミュレーション、動画のグレーディングの多くは、.cube形式で共有されています。Apertureは、.cubeファイルをLUTレイヤーとして読み込みます。テーブルはブラウザ内で解析され、バイト値に量子化されて3DテクスチャとしてGPUにアップロードされ、1920 pxのプレビューのすべてのピクセルについてトリリニア補間でサンプリングされます。適用されるのは、スタックでその下にある露光量、トーンカーブ、カラーなどのレイヤーのあとです。「強度」スライダーで、元のピクセルとルックアップ後のピクセルをブレンドします。LUTのテキストはプロジェクトのドキュメント内に保存されるので、エクスポート用のサーバーも同じテーブルを読み取り、同じ補間で元の画像にフルサイズで適用します。そのため、動画素材用に作ったグレーディングも、24メガピクセルの静止画に意図どおりそのまま反映されます。',
