        '.cubeファイルはプレーンテキストです。LUT_3D_SIZE Nの行でグリッドを宣言し、任意のTITLE、DOMAIN_MIN、DOMAIN_MAX、LUT_3D_INPUT_RANGEの行は読み飛ばされ、#で始まる行はコメントです。続いて三つの浮動小数点数からなる行がN x N x N行並び、赤が最も速く変化し、次に緑、最後に青が変化します。したがって、サイズ33のキューブは35,937行、サイズ65のキューブは274,625行になります。',
        'パーサーが受け付けるヘッダーは2から65までです。LUT_1D_SIZEを宣言したファイルは、3Dテーブルにしか対応していないため拒否されます。テキストの上限は1 MB（1,048,576バイト）です。小数点以下六桁の値を持つサイズ33のテーブルはすでに約970 KBあるため、上限に収まる一般的なグリッドのうち最大のものは33です。サイズ65のファイルは約7 MBになり、解析前にサイズ超過として拒否されます。',
        'テーブルのすべての値は round(value x 255) で0〜255にクランプしたバイト値に量子化され、RGB8の3Dテクスチャとしてアップロードできるようになります。0.5という値は 128/255 = 0.50196 になります。精度が失われるのはここだけで、その差は8ビットのエクスポートの許容範囲を下回ります。',
        'ルックアップはトリリニア補間です。入力の色を各軸で0〜N-1にスケールし、下側のセルのインデックスを floor(value) として上限をN-2に抑えます。結果は、周囲の八つの要素の間を赤、緑、青の順にlerpで補間したものです。出力は lerp(input, lookup, intensity) なので、強度0.6ではテーブルによるシフトの60パーセントが反映されます。',
