        'カラー：Labのaとbのチャンネルを、シグマが6 cピクセルの分離可能なガウスでぼかします。cは「カラー」スライダーの値を100で割ったものなので、「カラー」50はシグマ3 px、「カラー」100はシグマ6 pxです。タップはマイナスceil(3 sigma)からプラスceil(3 sigma)までで、float64で正規化され、端のピクセルは複製されます。',
        'フィルター処理したL、a、bは、標準の逆行列でsRGBに戻され、結果は0..1にクランプされます。ウィンドウとシグマはピクセル単位なので、同じスライダー値でも、6000 pxの元画像より1920 pxのプレビューのほうが、画面に占める割合として広い範囲が滑らかになります。結果は100%ズームで判断し、エクスポートはウィンドウに合わせたプレビューよりやや弱めに滑らかになると考えてください。',
        '「輝度」が0ならバイラテラルの処理は完全に省略され、「カラー」が0ならガウスの処理が省略されます。両方を0にしたレイヤーは、ごく弱いぼかしではなく、まったく何もしない恒等変換になります。',
        'プレビューは、写真の1920 pxのコピーからお使いのGPUがWebGL2で描画し、エクスポートされるファイルは、同じ式を使って当社のサーバーで元の画像からフル解像度で書き出されます。両者の差は、公開している許容範囲内に収まります。ノイズ軽減はApertureの一致ポリシーで最も緩い許容範囲が設定されており、8ビットで平均誤差は最大3レベル、最大誤差は12レベルです。これに対し、カラー調整は平均1レベルに抑えられ、粒子はビット単位で完全に一致します。',
