      intro: 'Apertureのディテールパネルにある周辺光量補正セクションは、各ピクセルに、画面の中心からの距離に応じた係数を掛けます。「量」の範囲は-100〜100です。負の値では周辺が暗くなり、視線を中央へ引き込む定番の見た目になります。正の値では周辺が明るくなり、開放で撮ったレンズに自然に生じる周辺減光を打ち消せます。「中心点」は効果が始まる位置、「ぼかし」は効果がどれだけゆるやかに強まるか、「丸み」は形が長方形の画面に沿うか円に沿うかを決め、「ハイライト」は明るいピクセルが暗くなるのを防ぎます。ほかと同じディテールレイヤーなので、マスクをかけたり、不透明度で弱めたり、元に戻したりできます。お使いのGPUでのプレビューとサーバーでのエクスポートは、同じ距離の尺度と同じsmoothstepのランプを使います。',
